format-code-task-000173.build_env_cmd:
#!/bin/bash
cd /testbed

# Switch to JDK 11 (required for Kotlin 1.5.21 compatibility)
dev-switch java 11

# Set JDK_18 for target compatibility 1.8
export JDK_18=/usr/lib/jvm/temurin-8-jdk-amd64

# Set up Gradle init script to fix grgit-core dependency resolution
mkdir -p /root/.gradle/init.d
cat > /root/.gradle/init.d/fix-grgit.gradle << 'INITEOF'
allprojects {
    buildscript {
        repositories {
            maven { url '/root/.m2-local' }
            maven { url 'https://plugins.gradle.org/m2/' }
        }
    }
    repositories {
        maven { url '/root/.m2-local' }
        maven { url 'https://plugins.gradle.org/m2/' }
    }
}
INITEOF

# Set up local Maven repo with grgit-core 4.0.2 (substitute with 4.1.1)
LOCAL_REPO="/root/.m2-local/org/ajoberstar/grgit/grgit-core/4.0.2"
if [ ! -f "$LOCAL_REPO/grgit-core-4.0.2.jar" ]; then
    mkdir -p "$LOCAL_REPO"
    curl -sL "https://plugins.gradle.org/m2/org/ajoberstar/grgit/grgit-core/4.1.1/grgit-core-4.1.1.jar" -o "$LOCAL_REPO/grgit-core-4.0.2.jar"
    curl -sL "https://plugins.gradle.org/m2/org/ajoberstar/grgit/grgit-core/4.1.1/grgit-core-4.1.1.pom" | sed 's/4.1.1/4.0.2/g' > "$LOCAL_REPO/grgit-core-4.0.2.pom"
    curl -sL "https://plugins.gradle.org/m2/org/ajoberstar/grgit/grgit-core/4.1.1/grgit-core-4.1.1.module" | sed 's/4.1.1/4.0.2/g' > "$LOCAL_REPO/grgit-core-4.0.2.module"
    cd "$LOCAL_REPO" && for f in *.jar *.pom *.module; do md5sum "$f" | awk '{print $1}' > "${f}.md5"; sha1sum "$f" | awk '{print $1}' > "${f}.sha1"; done
    cd /testbed
fi

# Run the target test
./gradlew :graphql-dgs-spring-webflux-autoconfigure:test --tests "com.netflix.graphql.dgs.webflux.autoconfiguration.GraphiQlCustomEndpoint" --no-daemon

